// Initialize Sidebar
function initSidebar() {
	setActiveSidebarLink();

	// Handle collapse toggle icon rotation for Accounts
	$('#accountsSubmenu').on('show.bs.collapse', function () {
		$('.dashboard-sidebar__toggle[data-bs-target="#accountsSubmenu"]').attr('aria-expanded', 'true');
	});

	$('#accountsSubmenu').on('hide.bs.collapse', function () {
		$('.dashboard-sidebar__toggle[data-bs-target="#accountsSubmenu"]').attr('aria-expanded', 'false');
	});

	// Handle collapse toggle icon rotation and active state for Settings
	$('#settingsSubmenu').on('show.bs.collapse', function () {
		$('.dashboard-sidebar__toggle[data-bs-target="#settingsSubmenu"]').attr('aria-expanded', 'true');
		// Add active class to Settings link when dropdown opens
		$('.settings-link-toggle').addClass('active');
	});

	$('#settingsSubmenu').on('hide.bs.collapse', function () {
		$('.dashboard-sidebar__toggle[data-bs-target="#settingsSubmenu"]').attr('aria-expanded', 'false');
		// Only remove active if not on any settings-related page
		const currentPage = window.location.pathname.split('/').filter(Boolean).pop() || '';
		const settingsPages = ['system-settings', 'taxes', 'add-taxes', 'measurement-unit', 'add-measurement', 'ware-house', 'add-ware-house', 'discount', 'add-discount', 'vendor', 'add-vendor', 'customer', 'add-customer'];
		if (!settingsPages.includes(currentPage)) {
			$('.settings-link-toggle').removeClass('active');
		}
	});

	// Handle Settings link click to toggle dropdown
	$(document).on('click', '.settings-link-toggle', function (e) {
		e.preventDefault();
		e.stopPropagation();
		const toggleBtn = $('.dashboard-sidebar__toggle[data-bs-target="#settingsSubmenu"]');
		if (toggleBtn.length) {
			// Manually toggle the collapse by clicking the toggle button
			toggleBtn[0].click();
		}
	});

	// Handle sidebar toggle button click
	$(document).on('click', '.sidebar-toggle', function (e) {
		e.preventDefault();
		$('.dashboard-sidebar').toggleClass('active');
		$('.sidebar-overlay').toggleClass('active');
		$('body').toggleClass('sidebar-open');
	});

	// Handle overlay click to close sidebar
	$(document).on('click', '.sidebar-overlay', function (e) {
		$('.dashboard-sidebar').removeClass('active');
		$('.sidebar-overlay').removeClass('active');
		$('body').removeClass('sidebar-open');
	});
}

function setActiveSidebarLink() {
	// Get current page path (Laravel routes don't have .php extension)
	const currentPath = window.location.pathname;
	const currentPage = currentPath.split('/').filter(Boolean).pop() || '';
	// Normalize path - remove trailing slash except for root
	let fullPath = currentPath.replace(/\/$/, '');
	if (fullPath === '') fullPath = '/';
	
	// Get base path if exists (e.g., /backend/web-portal/public)
	const pathParts = currentPath.split('/').filter(Boolean);
	const basePath = pathParts.length > 1 ? '/' + pathParts.slice(0, -1).join('/') : '';

	// Remove active class from all links
	$('.dashboard-sidebar__list a').removeClass('active');
	$('.dashboard-sidebar__submenu-link').removeClass('active');

	// Check for product-related pages - highlight Products link
	const productPages = ['add-products', 'category', 'sub-category', 'all-products'];
	if (productPages.includes(currentPage)) {
		$('.dashboard-sidebar__list a').each(function() {
			const href = $(this).attr('href');
			if (href && (href.includes('all-products') || href.includes('products'))) {
				$(this).addClass('active');
			}
		});
		// Don't return early for all-products as it needs normal matching too
		if (currentPage !== 'all-products') {
			return; // Exit early for other product pages
		}
	}

	// Check for settings pages first
	const systemSettingsPages = ['system-settings'];
	const generalSettingsPages = ['taxes', 'add-taxes', 'measurement-unit', 'add-measurement', 'ware-house', 'add-ware-house', 'discount', 'add-discount', 'vendor', 'add-vendor', 'customer', 'add-customer'];
	const allSettingsPages = [...systemSettingsPages, ...generalSettingsPages];
	
	if (allSettingsPages.includes(currentPage)) {
		// Highlight settings parent link
		$('.settings-link-toggle').addClass('active');

		// Expand settings submenu
		const settingsSubmenu = document.getElementById('settingsSubmenu');
		if (settingsSubmenu) {
			const bsCollapse = new bootstrap.Collapse(settingsSubmenu, {
				toggle: false
			});
			bsCollapse.show();
		}

		// If it's system-settings page, highlight System Settings link
		if (systemSettingsPages.includes(currentPage)) {
			$('.dashboard-sidebar__submenu-link').each(function() {
				const href = $(this).attr('href');
				if (href && href.includes('system-settings')) {
					$(this).addClass('active');
				}
			});
		}
		// For all general settings pages, highlight General Settings link (taxes)
		else if (generalSettingsPages.includes(currentPage)) {
			$('.dashboard-sidebar__submenu-link').each(function() {
				const href = $(this).attr('href');
				if (href && href.includes('taxes')) {
					$(this).addClass('active');
				}
			});
		}
		return; // Exit early to prevent accounts logic from running
	}

	// Find and add active class to current page link by matching href
	$('.dashboard-sidebar__list a, .dashboard-sidebar__submenu-link').each(function () {
		const href = $(this).attr('href');
		if (!href) return;
		
		// Extract path from href (handle both relative and absolute URLs)
		let hrefPath = href.replace(/^https?:\/\/[^\/]+/, '');
		hrefPath = hrefPath.replace(/\/$/, '') || '/';
		
		// Check if this link should be active
		let shouldBeActive = false;
		
		// Normalize both paths for comparison (remove trailing slashes)
		const normalizedHref = hrefPath === '/' ? '/' : hrefPath;
		const normalizedCurrent = fullPath === '/' ? '/' : fullPath;
		
		// For root path (/), only match if current path is also root (no page segments)
		if (normalizedHref === '/') {
			// Only active if we're on root - check if there's a page segment in current path
			const hasPageSegment = currentPage && currentPage !== '';
			shouldBeActive = !hasPageSegment && (normalizedCurrent === '/' || currentPath.endsWith('/'));
		}
		// For other paths, match exact or if current path contains the href path
		else {
			// Exact match
			if (normalizedCurrent === normalizedHref) {
				shouldBeActive = true;
			}
			// Current path ends with href path
			else if (currentPath.endsWith(normalizedHref) || currentPath.endsWith(normalizedHref + '/')) {
				shouldBeActive = true;
			}
			// Check if current page matches the last segment of href
			else if (currentPage && normalizedHref.split('/').pop() === currentPage) {
				shouldBeActive = true;
			}
		}
		
		if (shouldBeActive) {
			$(this).addClass('active');

			// If it's a submenu link, check which parent it belongs to
			const $submenuLink = $(this);
			if ($submenuLink.hasClass('dashboard-sidebar__submenu-link')) {
				// Check if it's in accounts submenu
				if ($submenuLink.closest('#accountsSubmenu').length > 0) {
					// Expand accounts submenu
					const accountsSubmenu = document.getElementById('accountsSubmenu');
					if (accountsSubmenu) {
						const bsCollapse = new bootstrap.Collapse(accountsSubmenu, {
							toggle: false
						});
						bsCollapse.show();
					}

					// Highlight accounts parent link
					$('.dashboard-sidebar__link').each(function() {
						if ($(this).attr('href') && $(this).attr('href').includes('accounts')) {
							$(this).addClass('active');
						}
					});
				}
				// Check if it's in settings submenu
				else if ($submenuLink.closest('#settingsSubmenu').length > 0) {
					// Expand settings submenu
					const settingsSubmenu = document.getElementById('settingsSubmenu');
					if (settingsSubmenu) {
						const bsCollapse = new bootstrap.Collapse(settingsSubmenu, {
							toggle: false
						});
						bsCollapse.show();
					}

					// Highlight settings parent link
					$('.settings-link-toggle').addClass('active');
				}
			}
		}
	});

	// Special handling for accounts page
	if (currentPage === 'accounts' || fullPath.includes('/accounts')) {
		$('.dashboard-sidebar__link').each(function() {
			if ($(this).attr('href') && $(this).attr('href').includes('accounts')) {
				$(this).addClass('active');
			}
		});
		// Don't auto-expand dropdown for accounts page itself
		return; // Exit early
	}

	// Check for accounts sub-pages (but exclude settings pages)
	const accountsSubPages = ['cashbook', 'expense', 'expenses', 'payroll', 'payroll-process', 'loan-and-advances', 'grant-new-loan-and-advance', 'profit-report', 'loss-report', 'revenue-report', 'new-cashbook-transaction'];
	const isAccountsSubPage = accountsSubPages.includes(currentPage) ||
		(currentPage.includes('expense') && !currentPage.includes('settings')) ||
		(currentPage.includes('expenses') && !currentPage.includes('settings')) ||
		(currentPage.includes('payroll') && !currentPage.includes('settings')) ||
		(currentPage.includes('loan') && !currentPage.includes('settings')) ||
		(currentPage.includes('profit') && !currentPage.includes('settings')) ||
		(currentPage.includes('loss') && !currentPage.includes('settings')) ||
		(currentPage.includes('revenue') && !currentPage.includes('settings')) ||
		(currentPage.includes('cashbook') && !currentPage.includes('settings'));

	if (isAccountsSubPage) {
		// Expand accounts submenu
		const accountsSubmenu = document.getElementById('accountsSubmenu');
		if (accountsSubmenu) {
			const bsCollapse = new bootstrap.Collapse(accountsSubmenu, {
				toggle: false
			});
			bsCollapse.show();
		}

		// Highlight accounts parent link
		$('.dashboard-sidebar__link').each(function() {
			if ($(this).attr('href') && $(this).attr('href').includes('accounts')) {
				$(this).addClass('active');
			}
		});

		// Highlight specific submenu links based on current page
		$('.dashboard-sidebar__submenu-link').each(function() {
			const href = $(this).attr('href');
			if (!href) return;
			
			const hrefPath = href.replace(/^https?:\/\/[^\/]+/, '').replace(/\/$/, '') || '/';
			
			if (fullPath === hrefPath || (hrefPath !== '/' && currentPath.includes(hrefPath))) {
				$(this).addClass('active');
			} else if (
				(currentPage.includes('cashbook') && href.includes('cashbook')) ||
				(currentPage.includes('expense') && href.includes('expense')) ||
				(currentPage.includes('payroll') && href.includes('payroll')) ||
				(currentPage.includes('loan') && href.includes('loan-and-advances')) ||
				(currentPage.includes('profit') && href.includes('profit-report')) ||
				(currentPage.includes('loss') && href.includes('loss-report')) ||
				(currentPage.includes('revenue') && href.includes('revenue-report'))
			) {
				$(this).addClass('active');
		}
		});
	}
}

function replaceHash() {
	document.querySelectorAll("a").forEach((a) => {
		let href = a.getAttribute("href");
		a.href = href ?
			href.startsWith("#") && href.endsWith("#") ?
			href.replace("#", "javascript:void(0)") :
			href :
			"javascript:void(0)";
	});
}

// Stock Performance Chart (Bar Chart)
function stockPerformanceChart() {
	const stockPerformanceCtx = document.getElementById('stockPerformanceChart').getContext('2d');
	const stockPerformanceChart = new Chart(stockPerformanceCtx, {
		type: 'bar',
		data: {
			labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
			datasets: [{
				label: 'Last Week',
				data: [6, 5, 3, 4, 2, 7, 5],
				backgroundColor: '#70504B',
				borderRadius: 10
			}, {
				label: 'This Week',
				data: [9, 4, 4, 5, 3, 6, 7],
				backgroundColor: '#FE9874',
				borderRadius: 10
			}]
		},
		options: {
			responsive: true,
			maintainAspectRatio: true,
			plugins: {
				legend: {
					display: false
				},
				tooltip: {
					enabled: true
				}
			},
			scales: {
				y: {
					beginAtZero: true,
					max: 10,
					ticks: {
						stepSize: 2,
						font: {
							size: 11
						},
						color: '#999'
					},
					grid: {
						color: '#F5F5F5',
						drawBorder: false
					}
				},
				x: {
					grid: {
						display: false,
						drawBorder: false
					},
					ticks: {
						font: {
							size: 11
						},
						color: '#666'
					}
				}
			}
		}
	});
}

